/**
 * `defineHook` — authored at `agent/hooks/<slug>.ts`.
 *
 * Hooks subscribe to the session event stream and run side effects after
 * each event is durably recorded (audit logging, metrics, persisting
 * transcripts to your own database). Handlers are observe-only.
 *
 * ```ts
 * import { defineHook } from "@grok/agent-sdk/hooks";
 *
 * export default defineHook({
 *   events: {
 *     async "turn.completed"(event, ctx) {
 *       const prior = await ctx.host.kv.get("last-result");
 *       const notes = await ctx.host.files.read("notes.md");
 *       console.log("turn done", ctx.session.id, event.data.usage, prior, notes);
 *     },
 *   },
 * });
 * ```
 */
import { brandDefinition } from "./internal/brand.js";
export function defineHook(config) {
    return brandDefinition("hook", config);
}
